  this->state.unknown_11C84->slots[0].riseAngle = 0;
  this->state.unknown_11C84->slots[1].riseAngle = 180;
  this->state.unknown_11C84->slots[0].alphaB = 200;
  this->state.unknown_11C84->slots[1].alphaB = 200;
